//! @generated by xtask split-cards.
use super::prelude::*;

/// Splash (Uncommon, 1 energy, Self). Generate 3 distinct Attack cards
/// from the non-owning character pools, optionally upgraded, present them
/// as a single-pick skippable card choice; the chosen card is set free for
/// the turn and moved to hand.
///
/// Source of truth:
/// `../sts2-wiki/decompiled/v0.103.2/MegaCrit.Sts2.Core.Models.Cards/Splash.cs`.
///
/// Bead `sts2-rs-9qlp` left this a marker; re-bodied under
/// `sts2-rs-6ynt.8-splash`, then corrected for the `card:SPLASH`
/// coverage-sweep divergence (`docs/audits/2026-06-03-ic-coverage-divergences-v2.json`).
/// The prior port collapsed the choice into a single uniform `next_int`
/// sample, which neither matched C#'s `GetDistinctForCombat(3)` shuffle
/// read-pattern nor presented the choose-a-card screen — desyncing
/// `combat_card_generation` and landing the wrong card. This now mirrors
/// C#: generate 3 **distinct** Attacks from the other-character pools
/// (shuffle off `combat_card_generation`, the `TakeRandom(3)` read-pattern
/// shared with AttackPotion/SkillPotion via
/// [`super::helpers::distinct_cross_character_attack_ids`]), upgrade them
/// iff Splash is upgraded, and open the single-pick skippable
/// `AddGeneratedFreeToHand` choice (C# `SetToFreeThisTurn` → add to hand).
pub(crate) fn play_splash(state: &mut CombatState, _t: Option<CreatureUid>) -> EffectResult {
    // C# `GetDistinctForCombat(cards, 3, …)` — Splash always generates 3.
    let ids = super::helpers::distinct_cross_character_attack_ids(state, 3);
    if ids.is_empty() {
        return EffectResult::Resolved;
    }
    // C# `Splash.OnPlay` upgrades EACH generated card when Splash itself is
    // upgraded, before the choose-a-card screen — so the chosen card is
    // upgraded. The `AddGeneratedFreeToHand` resolver materialises only the
    // picked id with this `upgraded` flag.
    let upgraded = current_upgraded(state);
    let options: Vec<sts2_core::ChoiceOption> = ids
        .iter()
        .map(|&card_id| sts2_core::ChoiceOption {
            card_id,
            upgraded,
            card_uid: None,
            source_pile: None,
        })
        .collect();
    state.request_card_choice(
        sts2_core::ChoiceKind::AddGeneratedFreeToHand,
        options,
        1,
        1,
        true,
    );
    EffectResult::Resolved
}

#[must_use]
pub(crate) const fn spec() -> CardSpec {
    super::helpers::splash()
}

#[allow(clippy::unnecessary_wraps, dead_code)]
pub(crate) fn upgrade() -> Option<CardUpgradeDelta> {
    None
}
